import { getDivergentPointIndex } from './get-divergent-point-index.js';
import { ChartLegendOrientation } from '../../../../types/legend.js';
import type { DivergentPointMetadata } from '../types/range-legend.internal.js';
import type { RangeItem } from '../types/range-legend.js';

export const getDivergentPointData = (
  items: RangeItem[],
  orientation: ChartLegendOrientation,
  width: number,
  height: number,
): DivergentPointMetadata => {
  const containerSize = orientation === 'horizontal' ? width : height;

  const divergentIndex = getDivergentPointIndex(items);

  const size = containerSize / items.length;

  return {
    size,
    label: items[divergentIndex]?.from.toString() ?? '',
    index: divergentIndex,
  };
};
